    "html": "<div class=\"page-header\">\n              <span class=\"header-tag\">TRAINING ONLY</span>\n              <span class=\"header-muted\">LANDING / GEAR</span>\n            </div>\n\n            <h1 class=\"page-title\">EMER - LDG GR EXTENTION FAIL</h1>\n            <div class=\"warning-box caution-box\">If landing gear extension fails, maintain controlled approach and assess available alternate gear configuration.</div>\n\n            <div class=\"qa-row\">\n              <span class=\"qa-label\">1. Flight Mode</span>\n              <span class=\"dots\" aria-hidden=\"true\"></span>\n              <input class=\"answer-input paper-answer-input\" id=\"paper-input-ANKA-LDG-001\" type=\"text\" data-qid=\"ANKA-LDG-001\" data-tab=\"tab-5\" data-answer=\"FORCE EXT\" data-accepted=\"FORCE EXT|FORCE EXTENSION|FORCE EXTEND\" maxlength=\"35\" autocomplete=\"off\" spellcheck=\"false\" oninput=\"App.onBoldFaceInput('ANKA-LDG-001')\" onkeydown=\"App.onBoldFaceKeyDown(event, 'ANKA-LDG-001')\" />\n            </div>\n            <div class=\"qa-row\">\n              <span class=\"qa-label\">2. ENG THR</span>\n              <span class=\"dots\" aria-hidden=\"true\"></span>\n              <input class=\"answer-input paper-answer-input\" id=\"paper-input-ANKA-LDG-002\" type=\"text\" data-qid=\"ANKA-LDG-002\" data-tab=\"tab-5\" data-answer=\"Decrease\" data-accepted=\"DECREASE|Turunkan|Decrease\" maxlength=\"30\" autocomplete=\"off\" spellcheck=\"false\" oninput=\"App.onBoldFaceInput('ANKA-LDG-002')\" onkeydown=\"App.onBoldFaceKeyDown(event, 'ANKA-LDG-002')\" />\n            </div>\n            <div class=\"qa-row\">\n              <span class=\"qa-label\">3. System</span>\n              <span class=\"dots\" aria-hidden=\"true\"></span>\n              <input class=\"answer-input paper-answer-input\" id=\"paper-input-ANKA-LDG-003\" type=\"text\" data-qid=\"ANKA-LDG-003\" data-tab=\"tab-5\" data-answer=\"STOW\" data-accepted=\"STOW|STOWED\" maxlength=\"25\" autocomplete=\"off\" spellcheck=\"false\" oninput=\"App.onBoldFaceInput('ANKA-LDG-003')\" onkeydown=\"App.onBoldFaceKeyDown(event, 'ANKA-LDG-003')\" />\n            </div>\n            <div class=\"qa-row\">\n              <span class=\"qa-label\">4. Landing gear</span>\n              <span class=\"dots\" aria-hidden=\"true\"></span>\n              <input class=\"answer-input paper-answer-input\" id=\"paper-input-ANKA-LDG-004\" type=\"text\" data-qid=\"ANKA-LDG-004\" data-tab=\"tab-5\" data-answer=\"Consider POS 1 or POS 2\" data-accepted=\"CONSIDER POS 1 OR POS 2|POS 1 or POS 2|Consider POS 1 or POS 2|POS 1/POS 2|POS 1 atau POS 2\" maxlength=\"45\" autocomplete=\"off\" spellcheck=\"false\" oninput=\"App.onBoldFaceInput('ANKA-LDG-004')\" onkeydown=\"App.onBoldFaceKeyDown(event, 'ANKA-LDG-004')\" />\n            </div>\n            <div class=\"qa-row\">\n              <span class=\"qa-label\">5. Touchdown action</span>\n              <span class=\"dots\" aria-hidden=\"true\"></span>\n              <input class=\"answer-input paper-answer-input\" id=\"paper-input-ANKA-LDG-005\" type=\"text\" data-qid=\"ANKA-LDG-005\" data-tab=\"tab-5\" data-answer=\"CUT, at Touchdown\" data-accepted=\"CUT AT TOUCHDOWN|CUT, at Touchdown|CUT, AT TOUCHDOWN|CUT\" maxlength=\"40\" autocomplete=\"off\" spellcheck=\"false\" oninput=\"App.onBoldFaceInput('ANKA-LDG-005')\" onkeydown=\"App.onBoldFaceKeyDown(event, 'ANKA-LDG-005')\" />\n            </div>\n            <div class=\"qa-row\">\n              <span class=\"qa-label\">6. Backup plan</span>\n              <span class=\"dots\" aria-hidden=\"true\"></span>\n              <input class=\"answer-input paper-answer-input\" id=\"paper-input-ANKA-LDG-006\" type=\"text\" data-qid=\"ANKA-LDG-006\" data-tab=\"tab-5\" data-answer=\"Consider BACKUP at Touchdown\" data-accepted=\"Consider BACKUP at Touchdown|BACKUP|BACKUP AT TOUCHDOWN|CONSIDER BACKUP AT TOUCHDOWN\" maxlength=\"55\" autocomplete=\"off\" spellcheck=\"false\" oninput=\"App.onBoldFaceInput('ANKA-LDG-006')\" onkeydown=\"App.onBoldFaceKeyDown(event, 'ANKA-LDG-006')\" />\n            </div>\n            <div class=\"qa-row\">\n              <span class=\"qa-label\">7. Engine thrust</span>\n              <span class=\"dots\" aria-hidden=\"true\"></span>\n              <input class=\"answer-input paper-answer-input\" id=\"paper-input-ANKA-LDG-007\" type=\"text\" data-qid=\"ANKA-LDG-007\" data-tab=\"tab-5\" data-answer=\"As Required\" data-accepted=\"As Required|AS REQUIRED\" maxlength=\"30\" autocomplete=\"off\" spellcheck=\"false\" oninput=\"App.onBoldFaceInput('ANKA-LDG-007')\" onkeydown=\"App.onBoldFaceKeyDown(event, 'ANKA-LDG-007')\" />\n            </div>"
